-- Replaces legacy vocabulary with original content under new IDs. Referenced old content is retained privately so progress/history is not remapped.
-- Topic scope follows broad workplace scenarios described by ETS; no official test items or lesson text are reproduced.
BEGIN;

DO $guard$
BEGIN
  IF (SELECT count(*) FROM public.vocabulary_lessons) <> 20 THEN
    RAISE EXCEPTION 'Expected 20 vocabulary lessons before curriculum migration';
  END IF;
  IF (SELECT count(*) FROM public.vocabulary_words) <> 600 THEN
    RAISE EXCEPTION 'Expected 600 vocabulary words before curriculum migration';
  END IF;
END;
$guard$;

CREATE TABLE IF NOT EXISTS public.vocabulary_legacy_words (
  id text PRIMARY KEY,
  lesson_id text NOT NULL,
  sort_order integer NOT NULL,
  content jsonb NOT NULL,
  archived_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.vocabulary_legacy_words ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.vocabulary_legacy_words FROM anon, authenticated;

SELECT w.id, w.lesson_id, w.sort_order, w.content
FROM public.vocabulary_words AS w
WHERE EXISTS (SELECT 1 FROM public.vocabulary_progress AS p WHERE p.word_id = w.id)
   OR EXISTS (SELECT 1 FROM public.vocabulary_review_history AS h WHERE h.word_id = w.id)
ON CONFLICT (id) DO UPDATE
SET lesson_id = EXCLUDED.lesson_id,
    sort_order = EXCLUDED.sort_order,
    content = EXCLUDED.content;

DELETE FROM public.vocabulary_words;

ON CONFLICT (id) DO UPDATE
SET lesson_id = EXCLUDED.lesson_id,
    sort_order = EXCLUDED.sort_order,
    content = EXCLUDED.content;

UPDATE public.vocabulary_lessons AS target_lesson
SET content = replacement.content
FROM (VALUES
  ('lesson1', $toeic_payload_20261109${"id":"lesson1","title":"Business & Office","category":"Business","description":"Core vocabulary for office operations, documents, facilities, and everyday workplace administration.","tip":"Listen for who is responsible, what document is involved, and any deadline or location mentioned.","exercises":[{"id":"lesson1-exercise-1","wordId":"curr-lesson1-001","prompt":"Complete the sentence: Mina moved her _____ with the regional director to Thursday afternoon.","options":["form","appointment","headquarters","cubicle"],"answer":"appointment","explanation":"?appointment? means an arrangement to meet someone at a particular time. The sentence describes this meaning."},{"id":"lesson1-exercise-2","wordId":"curr-lesson1-025","prompt":"Complete the sentence: The assistant will _____ the updated safety guide to every department.","options":["schedule","submit","distribute","maintain"],"answer":"distribute","explanation":"?distribute? means to give or deliver something to several people or places. The sentence describes this meaning."},{"id":"lesson1-exercise-3","wordId":"curr-lesson1-029","prompt":"Complete the sentence: The _____ personnel files are stored in a locked cabinet.","options":["operation","personnel","policy","confidential"],"answer":"confidential","explanation":"?confidential? means intended to be kept private or secret. The sentence describes this meaning."},{"id":"lesson1-exercise-4","wordId":"curr-lesson1-023","prompt":"Complete the sentence: Facilities placed a lockable _____ near the payroll desks for confidential forms.","options":["filing cabinet","procedure","reception","receptionist"],"answer":"filing cabinet","explanation":"?filing cabinet? means a cabinet with drawers for storing organized documents and records. The sentence describes this meaning."},{"id":"lesson1-exercise-5","wordId":"curr-lesson1-002","prompt":"Complete the sentence: The bank's downtown _____ will extend its opening hours during tax season.","options":["supplies","branch","supervisor","stationery"],"answer":"branch","explanation":"?branch? means a local office or part of a larger organization. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson2', $toeic_payload_20261109${"id":"lesson2","title":"Meetings & Conferences","category":"Business","description":"Words for planning meetings, exchanging ideas, presenting proposals, and recording decisions.","tip":"Meeting questions often test sequence: an item is proposed, discussed, decided, and recorded.","exercises":[{"id":"lesson2-exercise-1","wordId":"curr-lesson2-001","prompt":"Complete the sentence: The chair circulated the _____ so members could prepare questions in advance.","options":["session","speaker","agenda","venue"],"answer":"agenda","explanation":"?agenda? means a list of topics to be discussed at a meeting. The sentence describes this meaning."},{"id":"lesson2-exercise-2","wordId":"curr-lesson2-002","prompt":"Complete the sentence: The committee agreed to _____ until the revised figures were available.","options":["clarify","convene","demonstrate","adjourn"],"answer":"adjourn","explanation":"?adjourn? means to end a meeting or formal session. The sentence describes this meaning."},{"id":"lesson2-exercise-3","wordId":"curr-lesson2-003","prompt":"Complete the sentence: Each _____ received a name badge at the registration desk.","options":["attendee","consensus","debate","delegate"],"answer":"attendee","explanation":"?attendee? means a person who is present at an event or meeting. The sentence describes this meaning."},{"id":"lesson2-exercise-4","wordId":"curr-lesson2-004","prompt":"Complete the sentence: The project lead held a morning _____ on the construction timetable.","options":["discussion","briefing","facilitator","handout"],"answer":"briefing","explanation":"?briefing? means a short meeting or report that gives essential information. The sentence describes this meaning."},{"id":"lesson2-exercise-5","wordId":"curr-lesson2-005","prompt":"Complete the sentence: The annual _____ will bring suppliers together with retail managers.","options":["keynote","minutes","conference","moderator"],"answer":"conference","explanation":"?conference? means a formal meeting, often involving people from different organizations. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson3', $toeic_payload_20261109${"id":"lesson3","title":"Recruitment & Employment","category":"Employment","description":"Vocabulary for job applications, hiring decisions, workplace benefits, and career changes.","tip":"Distinguish the people (applicant, candidate, employer) from the documents and stages of hiring.","exercises":[{"id":"lesson3-exercise-1","wordId":"curr-lesson3-001","prompt":"Complete the sentence: Every _____ must provide two professional references.","options":["application","candidate","career","applicant"],"answer":"applicant","explanation":"?applicant? means a person who formally asks to be considered for a job or opportunity. The sentence describes this meaning."},{"id":"lesson3-exercise-2","wordId":"curr-lesson3-013","prompt":"Complete the sentence: The firm plans to _____ three designers before the new product launch.","options":["recruit","hire","resign","terminate"],"answer":"recruit","explanation":"?recruit? means to find and attract people to work for an organization. The sentence describes this meaning."},{"id":"lesson3-exercise-3","wordId":"curr-lesson3-021","prompt":"Complete the sentence: A _____ assistant will cover the reception desk during the renovation.","options":["resign","temporary","terminate","applicant"],"answer":"temporary","explanation":"?temporary? means lasting for a limited time rather than permanently. The sentence describes this meaning."},{"id":"lesson3-exercise-4","wordId":"curr-lesson3-006","prompt":"Complete the sentence: Please attach your _____ when replying to the research assistant posting.","options":["application","candidate","curriculum vitae","career"],"answer":"curriculum vitae","explanation":"?curriculum vitae? means a document outlining a person's education, qualifications, and work history. The sentence describes this meaning."},{"id":"lesson3-exercise-5","wordId":"curr-lesson3-002","prompt":"Complete the sentence: The online _____ asks candidates to list their recent work experience.","options":["salary","shortlist","skill","application"],"answer":"application","explanation":"?application? means a formal request for a job, place, or service. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson4', $toeic_payload_20261109${"id":"lesson4","title":"Marketing & Advertising","category":"Marketing","description":"Terms for promoting products, understanding customers, and measuring advertising reach.","tip":"Advertising describes the paid message; a campaign is the coordinated effort across channels.","exercises":[{"id":"lesson4-exercise-1","wordId":"curr-lesson4-002","prompt":"Complete the sentence: The newspaper's _____ lists the store's weekend hours and discounts.","options":["advertisement","exhibit","feature","flyer"],"answer":"advertisement","explanation":"?advertisement? means a public notice or message intended to promote something. The sentence describes this meaning."},{"id":"lesson4-exercise-2","wordId":"curr-lesson4-001","prompt":"Complete the sentence: The company will _____ its summer internship program on university websites.","options":["sponsor","advertise","target","persuade"],"answer":"advertise","explanation":"?advertise? means to promote a product, service, or event publicly. The sentence describes this meaning."},{"id":"lesson4-exercise-3","wordId":"curr-lesson4-018","prompt":"Complete the sentence: Customers can renew their memberships _____ without visiting a branch.","options":["commercial","consumer","online","coupon"],"answer":"online","explanation":"?online? means using or available through the internet. The sentence describes this meaning."},{"id":"lesson4-exercise-4","wordId":"curr-lesson4-015","prompt":"Complete the sentence: _____ showed that commuters prefer a monthly transit pass.","options":["product launch","public relations","brand awareness","market research"],"answer":"market research","explanation":"?market research? means the collection and analysis of information about customers and markets. The sentence describes this meaning."},{"id":"lesson4-exercise-5","wordId":"curr-lesson4-003","prompt":"Complete the sentence: The campaign's _____ includes first-time home buyers in the region.","options":["audience","advertisement","brand","campaign"],"answer":"audience","explanation":"?audience? means the people a message, performance, or product is intended to reach. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson5', $toeic_payload_20261109${"id":"lesson5","title":"Finance & Accounting","category":"Finance","description":"Essential terms for budgets, bookkeeping, business payments, and financial performance.","tip":"Track whether a figure is money received, money spent, or an amount still owed.","exercises":[{"id":"lesson5-exercise-1","wordId":"curr-lesson5-001","prompt":"Complete the sentence: The supplier asked the accounting team to verify its bank _____ details.","options":["loan","account","loss","margin"],"answer":"account","explanation":"?account? means a financial arrangement for recording money held or transactions made. The sentence describes this meaning."},{"id":"lesson5-exercise-2","wordId":"curr-lesson5-030","prompt":"Complete the sentence: Managers can _____ petty cash after signing the office ledger.","options":["deposit","expense","withdraw","financial"],"answer":"withdraw","explanation":"?withdraw? means to take money out of an account. The sentence describes this meaning."},{"id":"lesson5-exercise-3","wordId":"curr-lesson5-012","prompt":"Complete the sentence: The board requested a _____ update before approving the expansion.","options":["income","invoice","ledger","financial"],"answer":"financial","explanation":"?financial? means relating to money, finance, or the management of funds. The sentence describes this meaning."},{"id":"lesson5-exercise-4","wordId":"curr-lesson5-006","prompt":"Complete the sentence: Seasonal _____ improves when customers pay their invoices promptly.","options":["cash flow","purchase order","balance sheet","operating expense"],"answer":"cash flow","explanation":"?cash flow? means the movement of money into and out of a business. The sentence describes this meaning."},{"id":"lesson5-exercise-5","wordId":"curr-lesson5-002","prompt":"Complete the sentence: _____ closes the monthly books after all branch reports arrive.","options":["budget","accounting","charge","credit"],"answer":"accounting","explanation":"?accounting? means the work of recording and reporting an organization's financial activity. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson6', $toeic_payload_20261109${"id":"lesson6","title":"Sales & Customer Service","category":"Sales & Customer Service","description":"Vocabulary for prospecting, managing accounts, and resolving customer needs.","tip":"Listen for the customer’s need and the proposed next step; sales dialogues often test both.","exercises":[{"id":"lesson6-exercise-1","wordId":"curr-lesson6-002","prompt":"Complete the sentence: Mina assigned the new _____ to the representative covering the region.","options":["commission","revenue","lead","quotation"],"answer":"lead","explanation":"?lead? means A person or organization identified as a possible buyer.. The sentence describes this meaning."},{"id":"lesson6-exercise-2","wordId":"curr-lesson6-011","prompt":"Complete the sentence: Personalized support helped the firm _____ several major customers.","options":["resolve","upsell","cross-sell","retain"],"answer":"retain","explanation":"?retain? means To keep a customer or employee rather than lose them.. The sentence describes this meaning."},{"id":"lesson6-exercise-3","wordId":"curr-lesson6-009","prompt":"Complete the sentence: Nora took over the _____ after the branch added two new counties.","options":["sales territory","service request","sales pitch","sales forecast"],"answer":"sales territory","explanation":"?sales territory? means A geographic area or customer group assigned to a sales representative.. The sentence describes this meaning."},{"id":"lesson6-exercise-4","wordId":"curr-lesson6-003","prompt":"Complete the sentence: The regional office exceeded its quarterly sales _____.","options":["inquiry","quota","representative","satisfaction"],"answer":"quota","explanation":"?quota? means A sales target assigned for a specific period.. The sentence describes this meaning."},{"id":"lesson6-exercise-5","wordId":"curr-lesson6-004","prompt":"Complete the sentence: Her _____ increased after she renewed several large accounts.","options":["loyalty","subscription","commission","follow-up"],"answer":"commission","explanation":"?commission? means Payment calculated as a percentage of sales made.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson7', $toeic_payload_20261109${"id":"lesson7","title":"Travel & Transportation","category":"Travel & Transportation","description":"Terms for business trips, passenger services, and moving people or goods.","tip":"Separate scheduled travel details from disruptions such as delays or cancellations.","exercises":[{"id":"lesson7-exercise-1","wordId":"curr-lesson7-001","prompt":"Complete the sentence: The assistant emailed the revised _____ to everyone attending the trade fair.","options":["arrival","layover","connection","itinerary"],"answer":"itinerary","explanation":"?itinerary? means A plan listing the route and schedule of a trip.. The sentence describes this meaning."},{"id":"lesson7-exercise-2","wordId":"curr-lesson7-015","prompt":"Complete the sentence: Several employees _____ by train to avoid downtown traffic.","options":["commute","detour","chauffeur","passenger"],"answer":"commute","explanation":"?commute? means To travel regularly between home and work.. The sentence describes this meaning."},{"id":"lesson7-exercise-3","wordId":"curr-lesson7-006","prompt":"Complete the sentence: Keep the _____ ready when the gate agent calls your group.","options":["conductor","boarding pass","departure board","express delivery"],"answer":"boarding pass","explanation":"?boarding pass? means A document or digital pass that permits a passenger to board.. The sentence describes this meaning."},{"id":"lesson7-exercise-4","wordId":"curr-lesson7-002","prompt":"Complete the sentence: Passengers should reach the platform ten minutes before _____.","options":["gate","platform","departure","shuttle"],"answer":"departure","explanation":"?departure? means The act or scheduled time of leaving a place.. The sentence describes this meaning."},{"id":"lesson7-exercise-5","wordId":"curr-lesson7-003","prompt":"Complete the sentence: Upon _____, visiting engineers should collect their badges at reception.","options":["transit","delay","cancellation","arrival"],"answer":"arrival","explanation":"?arrival? means The act or scheduled time of reaching a destination.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson8', $toeic_payload_20261109${"id":"lesson8","title":"Hotels & Restaurants","category":"Hotels & Restaurants","description":"Language for lodging, guest services, dining, and event hospitality.","tip":"Hotel notices distinguish included amenities from optional services and additional charges.","exercises":[{"id":"lesson8-exercise-1","wordId":"curr-lesson8-001","prompt":"Complete the sentence: The travel coordinator booked _____ near the training venue.","options":["accommodation","beverage","allergen","bill"],"answer":"accommodation","explanation":"?accommodation? means A place or arrangement that provides lodging.. The sentence describes this meaning."},{"id":"lesson8-exercise-2","wordId":"curr-lesson8-015","prompt":"Complete the sentence: The hotel offers _____ coffee in the lobby before the morning seminar.","options":["porter","complimentary","occupancy","concierge"],"answer":"complimentary","explanation":"?complimentary? means Provided free of charge as a courtesy.. The sentence describes this meaning."},{"id":"lesson8-exercise-3","wordId":"curr-lesson8-005","prompt":"Complete the sentence: Please leave the signed delivery form at the _____.","options":["service charge","room service","front desk","room attendant"],"answer":"front desk","explanation":"?front desk? means The hotel reception area where guests receive assistance.. The sentence describes this meaning."},{"id":"lesson8-exercise-4","wordId":"curr-lesson8-002","prompt":"Complete the sentence: The _____ took the visiting auditors’ cases to their rooms.","options":["concierge","housekeeping","amenity","porter"],"answer":"porter","explanation":"?porter? means A hotel employee who carries guests’ luggage and may assist on arrival.. The sentence describes this meaning."},{"id":"lesson8-exercise-5","wordId":"curr-lesson8-003","prompt":"Complete the sentence: The hotel’s _____ rose during the annual industry conference.","options":["occupancy","suite","check-out","confirmation"],"answer":"occupancy","explanation":"?occupancy? means The number or proportion of rooms being used.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson9', $toeic_payload_20261109${"id":"lesson9","title":"Shopping & Retail","category":"Shopping & Retail","description":"Useful terms for product selection, store operations, and customer purchases.","tip":"Identify whether a retail problem concerns the item, its price, or the transaction.","exercises":[{"id":"lesson9-exercise-1","wordId":"curr-lesson9-001","prompt":"Complete the sentence: The manager moved seasonal _____ to the front of the store.","options":["checkout","merchandise","cashier","register"],"answer":"merchandise","explanation":"?merchandise? means Goods offered for sale in a store or by a business.. The sentence describes this meaning."},{"id":"lesson9-exercise-2","wordId":"curr-lesson9-029","prompt":"Complete the sentence: A _____ price reduction begins after the inventory count.","options":["exchange","return","storewide","clearance"],"answer":"storewide","explanation":"?storewide? means Applying to or available throughout an entire store.. The sentence describes this meaning."},{"id":"lesson9-exercise-3","wordId":"curr-lesson9-017","prompt":"Complete the sentence: The attendant brought a different size to the _____.","options":["warranty claim","loyalty card","shopping cart","fitting room"],"answer":"fitting room","explanation":"?fitting room? means A room where customers try on clothes before buying them.. The sentence describes this meaning."},{"id":"lesson9-exercise-4","wordId":"curr-lesson9-002","prompt":"Complete the sentence: Staff counted the _____ before the new catalog went to print.","options":["inventory","aisle","shelf","display"],"answer":"inventory","explanation":"?inventory? means The goods a business has available for sale or use.. The sentence describes this meaning."},{"id":"lesson9-exercise-5","wordId":"curr-lesson9-003","prompt":"Complete the sentence: A clerk checked the _____ for the requested jacket size.","options":["purchase","stockroom","vendor","supplier"],"answer":"stockroom","explanation":"?stockroom? means A room where a store keeps goods before displaying or selling them.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson10', $toeic_payload_20261109${"id":"lesson10","title":"Technology & Computers","category":"Technology & Computers","description":"Computer and software vocabulary for office work, troubleshooting, and digital collaboration.","tip":"For technical problems, note the affected device, the error, and the troubleshooting step already taken.","exercises":[{"id":"lesson10-exercise-1","wordId":"curr-lesson10-001","prompt":"Complete the sentence: The accounting _____ generates a monthly expense summary.","options":["update","backup","software","password"],"answer":"software","explanation":"?software? means Programs and operating instructions used by a computer.. The sentence describes this meaning."},{"id":"lesson10-exercise-2","wordId":"curr-lesson10-009","prompt":"Complete the sentence: Employees can _____ the updated handbook from the staff portal.","options":["restore","troubleshoot","upload","download"],"answer":"download","explanation":"?download? means To copy data from a remote system onto a local device.. The sentence describes this meaning."},{"id":"lesson10-exercise-3","wordId":"curr-lesson10-023","prompt":"Complete the sentence: Check that the new headset is _____ with the office phone system.","options":["compatible","browser","bandwidth","outage"],"answer":"compatible","explanation":"?compatible? means Able to work or be used together without problems.. The sentence describes this meaning."},{"id":"lesson10-exercise-4","wordId":"curr-lesson10-030","prompt":"Complete the sentence: The team moved shared documents to _____ for easier collaboration.","options":["troubleshoot","cloud storage","compatible","device"],"answer":"cloud storage","explanation":"?cloud storage? means Online storage that keeps files on remote servers for internet access.. The sentence describes this meaning."},{"id":"lesson10-exercise-5","wordId":"curr-lesson10-002","prompt":"Complete the sentence: IT replaced the damaged _____ before the design review.","options":["peripheral","encryption","hardware","software"],"answer":"hardware","explanation":"?hardware? means The physical equipment and components of a computer system.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson11', $toeic_payload_20261109${"id":"lesson11","title":"Manufacturing & Production","category":"Manufacturing","description":"Vocabulary for factory processes, equipment, output, and product quality.","tip":"Distinguish a flaw in a product from downtime in a production process.","exercises":[{"id":"lesson11-exercise-1","wordId":"curr-lesson11-001","prompt":"Complete the sentence: The _____ now installs each control panel in less than four minutes.","options":["yield","calibration","maintenance","assembly line"],"answer":"assembly line","explanation":"?assembly line? means A sequence of workstations where a product is assembled.. The sentence describes this meaning."},{"id":"lesson11-exercise-2","wordId":"curr-lesson11-021","prompt":"Complete the sentence: _____ rejected the lot after two measurements fell outside tolerance.","options":["quality control","foreperson","supply","technician"],"answer":"quality control","explanation":"?quality control? means The procedures used to ensure products meet required standards.. The sentence describes this meaning."},{"id":"lesson11-exercise-3","wordId":"curr-lesson11-002","prompt":"Complete the sentence: One _____ was held back after the labels showed an outdated model number.","options":["component","batch","defect","downtime"],"answer":"batch","explanation":"?batch? means A quantity of goods produced together in one run.. The sentence describes this meaning."},{"id":"lesson11-exercise-4","wordId":"curr-lesson11-003","prompt":"Complete the sentence: The plant expects to reach full _____ before the seasonal order rush.","options":["efficiency","tooling","capacity","fabrication"],"answer":"capacity","explanation":"?capacity? means The maximum amount a facility can produce or hold.. The sentence describes this meaning."},{"id":"lesson11-exercise-5","wordId":"curr-lesson11-004","prompt":"Complete the sentence: A supplier notified us that a _____ for the display unit was delayed.","options":["factory","inspection","stocktaking","component"],"answer":"component","explanation":"?component? means One part of a larger product or machine.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson12', $toeic_payload_20261109${"id":"lesson12","title":"Shipping & Logistics","category":"Logistics","description":"Vocabulary for packing, transporting, clearing, and delivering goods.","tip":"Check whether a shipping notice gives a dispatch date, arrival date, or delivery deadline.","exercises":[{"id":"lesson12-exercise-1","wordId":"curr-lesson12-001","prompt":"Complete the sentence: The broker requested a copy of the _____ before releasing the cargo.","options":["airway bill","manifest","order","package"],"answer":"airway bill","explanation":"?airway bill? means A document recording the terms and details of air-freight transport.. The sentence describes this meaning."},{"id":"lesson12-exercise-2","wordId":"curr-lesson12-007","prompt":"Complete the sentence: The warehouse will _____ the replacement parts this afternoon.","options":["airway bill","dispatch","cargo","carrier"],"answer":"dispatch","explanation":"?dispatch? means To send goods or a vehicle to a destination.. The sentence describes this meaning."},{"id":"lesson12-exercise-3","wordId":"curr-lesson12-021","prompt":"Complete the sentence: The receiver used the _____ to confirm the number of cartons in the delivery.","options":["consignment","customs","packing list","delivery"],"answer":"packing list","explanation":"?packing list? means A document listing the contents of a shipment and how they are packed.. The sentence describes this meaning."},{"id":"lesson12-exercise-4","wordId":"curr-lesson12-002","prompt":"Complete the sentence: The _____ was transferred to a refrigerated truck at the airport.","options":["storage","tracking","transshipment","cargo"],"answer":"cargo","explanation":"?cargo? means Goods carried by a ship, aircraft, or other vehicle.. The sentence describes this meaning."},{"id":"lesson12-exercise-5","wordId":"curr-lesson12-003","prompt":"Complete the sentence: The _____ will collect the cartons from the loading dock at noon.","options":["carrier","warehouse","logistics","container"],"answer":"carrier","explanation":"?carrier? means A company that transports goods or passengers.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson13', $toeic_payload_20261109${"id":"lesson13","title":"Contracts & Agreements","category":"Contracts","description":"Vocabulary for negotiated commitments, legal terms, and changes to agreements.","tip":"Look for the clause or condition that explains when a commitment applies.","exercises":[{"id":"lesson13-exercise-1","wordId":"curr-lesson13-001","prompt":"Complete the sentence: Both firms signed an _____ to share the research costs.","options":["confidentiality","agreement","consent","contract"],"answer":"agreement","explanation":"?agreement? means A negotiated arrangement accepted by two or more parties.. The sentence describes this meaning."},{"id":"lesson13-exercise-2","wordId":"curr-lesson13-002","prompt":"Complete the sentence: The supplier asked to _____ the delivery clause before signing.","options":["rescind","comply","amend","enforce"],"answer":"amend","explanation":"?amend? means To make a formal change to a document or agreement.. The sentence describes this meaning."},{"id":"lesson13-exercise-3","wordId":"curr-lesson13-024","prompt":"Complete the sentence: The offer remains _____ until the close of business on June 30.","options":["deadline","dispute","duration","valid"],"answer":"valid","explanation":"?valid? means Legally or officially acceptable and in effect.. The sentence describes this meaning."},{"id":"lesson13-exercise-4","wordId":"curr-lesson13-003","prompt":"Complete the sentence: A confidentiality _____ protects the client's technical drawings.","options":["clause","party","penalty","provision"],"answer":"clause","explanation":"?clause? means A separate section of a legal document that states a rule or condition.. The sentence describes this meaning."},{"id":"lesson13-exercise-5","wordId":"curr-lesson13-004","prompt":"Complete the sentence: The retailer made a six-month _____ to purchase the product.","options":["terms","commitment","breach","indemnity"],"answer":"commitment","explanation":"?commitment? means A promise or obligation to do something.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson14', $toeic_payload_20261109${"id":"lesson14","title":"Company Management","category":"Management","description":"Vocabulary for leadership, staffing, organizational structure, and strategy.","tip":"Management terms may describe a person's authority or a planned company action; use context to tell which.","exercises":[{"id":"lesson14-exercise-1","wordId":"curr-lesson14-002","prompt":"Complete the sentence: Senior management provides _____ of the branch expansion plan.","options":["shareholder","strategy","oversight","subordinate"],"answer":"oversight","explanation":"?oversight? means The act of supervising an activity or ensuring it is properly managed.. The sentence describes this meaning."},{"id":"lesson14-exercise-2","wordId":"curr-lesson14-007","prompt":"Complete the sentence: Finance and marketing will _____ on the new pricing plan.","options":["supervise","administer","assign","collaborate"],"answer":"collaborate","explanation":"?collaborate? means To work jointly with others on a task or project.. The sentence describes this meaning."},{"id":"lesson14-exercise-3","wordId":"curr-lesson14-006","prompt":"Complete the sentence: The _____ outlined the firm's priorities for the coming year.","options":["chief executive","mentorship","succession","restructure"],"answer":"chief executive","explanation":"?chief executive? means The highest-ranking manager responsible for leading a company.. The sentence describes this meaning."},{"id":"lesson14-exercise-4","wordId":"curr-lesson14-004","prompt":"Complete the sentence: Branch managers have _____ to approve routine expenses.","options":["staffing","authority","executive","hierarchy"],"answer":"authority","explanation":"?authority? means The power or right to make decisions or give instructions.. The sentence describes this meaning."},{"id":"lesson14-exercise-5","wordId":"curr-lesson14-005","prompt":"Complete the sentence: The _____ will review the expansion proposal at its quarterly meeting.","options":["initiative","leadership","board","manager"],"answer":"board","explanation":"?board? means A group elected or appointed to oversee an organization.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson15', $toeic_payload_20261109${"id":"lesson15","title":"Real Estate & Construction","category":"Property & Construction","description":"Vocabulary for property, leases, building work, and construction projects.","tip":"Construction notices distinguish an estimate from a permit, and a tenant from a landlord.","exercises":[{"id":"lesson15-exercise-1","wordId":"curr-lesson15-001","prompt":"Complete the sentence: The _____ revised the lobby plans to improve wheelchair access.","options":["landlord","lot","appraiser","architect"],"answer":"architect","explanation":"?architect? means A professional who designs buildings and prepares construction plans.. The sentence describes this meaning."},{"id":"lesson15-exercise-2","wordId":"curr-lesson15-017","prompt":"Complete the sentence: The _____ property includes a loading bay and space for heavy machinery.","options":["industrial","residential","structural","vacant"],"answer":"industrial","explanation":"?industrial? means Related to factories, manufacturing, or other large-scale production.. The sentence describes this meaning."},{"id":"lesson15-exercise-3","wordId":"curr-lesson15-022","prompt":"Complete the sentence: The firm specializes in _____ for small technology companies.","options":["setback","real estate","utility","vacant"],"answer":"real estate","explanation":"?real estate? means Land and buildings, especially considered as property for sale or rent.. The sentence describes this meaning."},{"id":"lesson15-exercise-4","wordId":"curr-lesson15-002","prompt":"Complete the sentence: The contractor compared the electrical work with the latest _____.","options":["property","site","blueprint","setback"],"answer":"blueprint","explanation":"?blueprint? means A detailed plan or technical drawing for a building or project.. The sentence describes this meaning."},{"id":"lesson15-exercise-5","wordId":"curr-lesson15-003","prompt":"Complete the sentence: The office _____ will remain open during the lobby renovation.","options":["utility","ventilation","excavation","building"],"answer":"building","explanation":"?building? means A structure with walls and a roof, used for a particular purpose.. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson16', $toeic_payload_20261109${"id":"lesson16","title":"Health & Medical","category":"Health & Medical","description":"Vocabulary for workplace wellness, medical appointments, and health services.","tip":"Listen for symptoms, treatment, and appointment details in medical and workplace announcements.","exercises":[{"id":"lesson16-exercise-1","wordId":"curr-lesson16-001","prompt":"Complete the sentence: The clinic offers a free _____ to employees once a year.","options":["checkup","patient","symptom","diagnosis"],"answer":"checkup","explanation":"?checkup? means a routine medical examination to assess a person?s health. The sentence describes this meaning."},{"id":"lesson16-exercise-2","wordId":"curr-lesson16-024","prompt":"Complete the sentence: He expects to _____ fully before the business trip.","options":["sterile","recover","checkup","clinic"],"answer":"recover","explanation":"?recover? means to become well again after illness or injury. The sentence describes this meaning."},{"id":"lesson16-exercise-3","wordId":"curr-lesson16-011","prompt":"Complete the sentence: The company updated its _____ insurance plan this year.","options":["contagious","sterile","medical","healthy"],"answer":"medical","explanation":"?medical? means related to health care or medicine. The sentence describes this meaning."},{"id":"lesson16-exercise-4","wordId":"curr-lesson16-002","prompt":"Complete the sentence: Employees can visit the _____ during the lunch break.","options":["claim","wellness","health","clinic"],"answer":"clinic","explanation":"?clinic? means a medical facility for outpatient care. The sentence describes this meaning."},{"id":"lesson16-exercise-5","wordId":"curr-lesson16-003","prompt":"Complete the sentence: A _____ will review the results before calling the patient.","options":["physician","exercise","therapy","therapist"],"answer":"physician","explanation":"?physician? means a qualified doctor. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson17', $toeic_payload_20261109${"id":"lesson17","title":"Education & Training","category":"Education & Training","description":"Terms for courses, professional development, instruction, and assessment.","tip":"Pay attention to course dates, prerequisites, enrollment instructions, and assessment deadlines.","exercises":[{"id":"lesson17-exercise-1","wordId":"curr-lesson17-001","prompt":"Complete the sentence: The finance _____ begins next Monday in the training room.","options":["seminar","course","workshop","curriculum"],"answer":"course","explanation":"?course? means a series of lessons on a subject. The sentence describes this meaning."},{"id":"lesson17-exercise-2","wordId":"curr-lesson17-012","prompt":"Complete the sentence: Employees can _____ in the language course through the portal.","options":["workshop","curriculum","enroll","syllabus"],"answer":"enroll","explanation":"?enroll? means to officially register for a course or program. The sentence describes this meaning."},{"id":"lesson17-exercise-3","wordId":"curr-lesson17-018","prompt":"Complete the sentence: Only _____ staff may operate the testing equipment.","options":["lecture hall","classroom","enroll","qualified"],"answer":"qualified","explanation":"?qualified? means having the skills or credentials needed. The sentence describes this meaning."},{"id":"lesson17-exercise-4","wordId":"curr-lesson17-010","prompt":"Complete the sentence: The orientation will take place in _____ B.","options":["lecture hall","attend","attendance","certificate"],"answer":"lecture hall","explanation":"?lecture hall? means a large room used for teaching groups. The sentence describes this meaning."},{"id":"lesson17-exercise-5","wordId":"curr-lesson17-002","prompt":"Complete the sentence: New-hire _____ includes a session on data security.","options":["tuition","training","mentor","mentoring"],"answer":"training","explanation":"?training? means the process of learning skills for a job or activity. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson18', $toeic_payload_20261109${"id":"lesson18","title":"Environment & Weather","category":"Environment & Weather","description":"Words for weather conditions, environmental impact, and sustainable operations.","tip":"Distinguish weather forecasts from longer-term climate and environmental reports.","exercises":[{"id":"lesson18-exercise-1","wordId":"curr-lesson18-001","prompt":"Complete the sentence: Severe _____ may delay the delivery scheduled for this afternoon.","options":["forecast","climate","weather","temperature"],"answer":"weather","explanation":"?weather? means the condition of the atmosphere at a particular time. The sentence describes this meaning."},{"id":"lesson18-exercise-2","wordId":"curr-lesson18-023","prompt":"Complete the sentence: Please _____ cardboard in the marked collection area.","options":["environmental","pollution","pollutant","recycle"],"answer":"recycle","explanation":"?recycle? means to process used materials so they can be used again. The sentence describes this meaning."},{"id":"lesson18-exercise-3","wordId":"curr-lesson18-011","prompt":"Complete the sentence: It will be _____ when the visiting team arrives.","options":["cloudy","renewable","solar","sustainable"],"answer":"cloudy","explanation":"?cloudy? means covered with or characterized by clouds. The sentence describes this meaning."},{"id":"lesson18-exercise-4","wordId":"curr-lesson18-002","prompt":"Complete the sentence: The _____ calls for heavy rain during the outdoor event.","options":["environment","forecast","pollution","pollutant"],"answer":"forecast","explanation":"?forecast? means a report predicting future weather or conditions. The sentence describes this meaning."},{"id":"lesson18-exercise-5","wordId":"curr-lesson18-003","prompt":"Complete the sentence: The report compares the region's _____ over several decades.","options":["emission","carbon","climate","conservation"],"answer":"climate","explanation":"?climate? means the usual weather conditions of a region over time. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson19', $toeic_payload_20261109${"id":"lesson19","title":"Daily Activities","category":"Daily Activities","description":"Practical verbs and nouns for routines, errands, schedules, and everyday work.","tip":"In listening questions, note time expressions and the order in which daily tasks occur.","exercises":[{"id":"lesson19-exercise-1","wordId":"curr-lesson19-001","prompt":"Complete the sentence: Her morning _____ includes checking the delivery schedule.","options":["reminder","arrangement","collection","routine"],"answer":"routine","explanation":"?routine? means a usual sequence of regular activities. The sentence describes this meaning."},{"id":"lesson19-exercise-2","wordId":"curr-lesson19-008","prompt":"Complete the sentence: I _____ the invoices by date before filing them.","options":["organize","prioritize","remind","arrange"],"answer":"organize","explanation":"?organize? means to arrange things in an orderly way. The sentence describes this meaning."},{"id":"lesson19-exercise-3","wordId":"curr-lesson19-003","prompt":"Complete the sentence: The _____ maintenance will begin after business hours.","options":["cleaning","scheduled","repair","laundry"],"answer":"scheduled","explanation":"?scheduled? means planned for a particular time. The sentence describes this meaning."},{"id":"lesson19-exercise-4","wordId":"curr-lesson19-004","prompt":"Complete the sentence: Linh does the _____ on Wednesday evenings after work.","options":["pick up","drop off","grocery shopping","household chore"],"answer":"grocery shopping","explanation":"?grocery shopping? means the activity of buying food and household supplies from a grocery store. The sentence describes this meaning."},{"id":"lesson19-exercise-5","wordId":"curr-lesson19-002","prompt":"Complete the sentence: I checked the bus _____ before leaving the office for the client visit.","options":["errand","calendar","reminder","timetable"],"answer":"timetable","explanation":"?timetable? means a plan showing the times when activities or events will happen. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb),
  ('lesson20', $toeic_payload_20261109${"id":"lesson20","title":"Common TOEIC Expressions","category":"Common TOEIC Expressions","description":"Useful phrases and expressions heard in workplace notices, requests, and conversations.","tip":"Identify the purpose of each expression: a request, a suggestion, a deadline, or a follow-up.","exercises":[{"id":"lesson20-exercise-1","wordId":"curr-lesson20-001","prompt":"Complete the sentence: Please send the revised quotation _____.","options":["as soon as possible","come up with","keep in touch","at your convenience"],"answer":"as soon as possible","explanation":"?as soon as possible? means at the earliest time that is practical. The sentence describes this meaning."},{"id":"lesson20-exercise-2","wordId":"curr-lesson20-002","prompt":"Complete the sentence: Reserve a visitor badge _____ to avoid delays.","options":["for your reference","in advance","in the meantime","as soon as possible"],"answer":"in advance","explanation":"?in advance? means before a particular time or event. The sentence describes this meaning."},{"id":"lesson20-exercise-3","wordId":"curr-lesson20-003","prompt":"Complete the sentence: I am contacting you _____ the regional manager.","options":["in advance","in charge of","on behalf of","according to"],"answer":"on behalf of","explanation":"?on behalf of? means as a representative of someone. The sentence describes this meaning."},{"id":"lesson20-exercise-4","wordId":"curr-lesson20-004","prompt":"Complete the sentence: Nora is _____ the conference registration desk.","options":["due to","instead of","regardless of","in charge of"],"answer":"in charge of","explanation":"?in charge of? means responsible for managing or controlling something. The sentence describes this meaning."},{"id":"lesson20-exercise-5","wordId":"curr-lesson20-005","prompt":"Complete the sentence: _____ the notice, the east entrance will remain closed.","options":["according to","prior to","no later than","look forward to"],"answer":"according to","explanation":"?according to? means as stated or reported by a source. The sentence describes this meaning."}]}$toeic_payload_20261109$::jsonb)
) AS replacement(id, content)
WHERE target_lesson.id = replacement.id;

DO $verify$
BEGIN
  IF (SELECT count(*) FROM public.vocabulary_words) <> 600
     OR (SELECT count(DISTINCT lower(content->>'word')) FROM public.vocabulary_words) <> 600 THEN
    RAISE EXCEPTION 'Curriculum must contain exactly 600 unique words';
  END IF;
  IF EXISTS (
    SELECT l.id FROM public.vocabulary_lessons AS l
    LEFT JOIN public.vocabulary_words AS w ON w.lesson_id = l.id
    GROUP BY l.id HAVING count(w.id) <> 30
  ) THEN
    RAISE EXCEPTION 'Each lesson must contain exactly 30 words';
  END IF;
  IF (SELECT count(*) FROM public.vocabulary_lessons
      WHERE jsonb_array_length(content->'exercises') = 5) <> 20 THEN
    RAISE EXCEPTION 'Each lesson must contain exactly five exercises';
  END IF;
  IF (SELECT count(*) FROM public.vocabulary_legacy_words) <
     (SELECT count(DISTINCT word_id) FROM public.vocabulary_progress) THEN
    RAISE EXCEPTION 'Legacy vocabulary archive is missing progress-linked words';
  END IF;
END;
$verify$;

COMMIT;
